 "content": "from collections import defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])

    # The all-zero column separates the framed pattern panel from the colored motifs.
    split = next(c for c in range(w) if all(grid[r][c] == 0 for r in range(h)))
    left = [row[:split] for row in grid]
    panel_w = split

    # Horizontal full-color rows form the boundaries between framed pattern cells.
    counts = defaultdict(int)
    for row in left:
        for value in row:
            if value:
                counts[value] += 1
    frame = max(counts, key=counts.get)
    boundaries = [r for r, row in enumerate(left) if all(v == frame for v in row)]

    # Each non-frame color on the right encodes one shape to stamp into its matching cavity.
    motifs = {}
    for r in range(h):
        for c in range(split + 1, w):
            color = grid[r][c]
            if color:
                motifs.setdefault(color, set()).add((r, c))
    normalized = {}
    for color, cells in motifs.items():
        min_r = min(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        normalized[color] = {(r - min_r, c - min_c) for r, c in cells}

    out = [row[:] for row in left]
    for top, bottom in zip(boundaries, boundaries[1:]):
        cavity = {(r - (top + 1), c - 1)
                  for r in range(top + 1, bottom)
                  for c in range(1, panel_w - 1)
                  if left[r][c] == 0}
        for color, shape in normalized.items():
            if cavity == shape:
                for r in range(top + 1, bottom):
                    for c in range(1, panel_w - 1):
                        if left[r][c] == 0:
                            # Paint only the cavity cells; the shape equality guarantees
                            # this is the exact motif footprint.
                            if (r - (top + 1), c - 1) in shape:
                                out[r][c] = color
                break
    return out
